using System;
using System.Collections.Generic;

namespace QuickJS;

/// <summary>
/// Bytecode interpreter for executing JavaScript functions.
/// </summary>
/// <remarks>
/// <para>
/// The interpreter executes bytecode generated by the parser/compiler.
/// It uses a stack-based virtual machine model where:
/// </para>
/// <list type="bullet">
/// <item>Values are pushed onto and popped from an operand stack</item>
/// <item>A program counter (PC) tracks the current instruction</item>
/// <item>Opcodes consume operands from the stack and push results</item>
/// </list>
/// <para>
/// Based on JS_CallInternal from QuickJS (quickjs.c lines 17356-20000+).
/// </para>
/// </remarks>
public sealed class Interpreter
{
    #region Fields

    private readonly JSContext _context;
    private readonly JSValue[] _stack;
    private int _stackPointer;
    private readonly int _maxStackSize;

    /// <summary>
    /// The current call frame containing locals, args, and var refs.
    /// </summary>
    private CallFrame? _currentFrame;

    #endregion

    #region Constructor

    /// <summary>
    /// Initializes a new instance of the <see cref="Interpreter"/> class.
    /// </summary>
    /// <param name="context">The JavaScript execution context.</param>
    /// <param name="stackSize">The maximum operand stack size.</param>
    public Interpreter(JSContext context, int stackSize = 512)
    {
        _context = context ?? throw new ArgumentNullException(nameof(context));
        _maxStackSize = stackSize;
        _stack = new JSValue[stackSize];
        _stackPointer = 0;
    }

    #endregion

    #region Properties

    /// <summary>
    /// Gets the execution context.
    /// </summary>
    public JSContext Context => _context;

    /// <summary>
    /// Gets the current stack pointer (number of values on the stack).
    /// </summary>
    public int StackPointer => _stackPointer;

    /// <summary>
    /// Gets the maximum stack size.
    /// </summary>
    public int MaxStackSize => _maxStackSize;

    /// <summary>
    /// Gets the available stack space.
    /// </summary>
    public int AvailableStackSpace => _maxStackSize - _stackPointer;

    /// <summary>
    /// Gets whether the stack is empty.
    /// </summary>
    public bool IsStackEmpty => _stackPointer == 0;

    /// <summary>
    /// Gets whether an exception has been thrown.
    /// </summary>
    public bool HasException => _context.HasException;

    /// <summary>
    /// Gets or sets the current call frame.
    /// </summary>
    public CallFrame? CurrentFrame
    {
        get => _currentFrame;
        set => _currentFrame = value;
    }

    #endregion

    #region Call Helpers

    private JSValue CallFunction(JSValue calleeVal, JSValue thisVal, JSValue[] args, bool isConstructor = false)
    {
        if (!calleeVal.IsObject)
        {
            _context.ThrowTypeError("Not a function");
            return JSValue.Exception;
        }

        var calleeObj = calleeVal.AsObject();
        if (calleeObj is JSFunction func)
        {
            // Native functions
            if (func.NativeFunction != null || func.NativeFunctionMagic != null)
            {
                try
                {
                    var result = func.CallNative(thisVal, args);
                    if (isConstructor && !result.IsObject)
                        return thisVal;
                    return result;
                }
                catch (JSException ex)
                {
                    _context.ThrowError(JSErrorType.Error, ex.Message);
                    return JSValue.Exception;
                }
            }

            // Bytecode functions
            var fd = func.FunctionDef;
            if (fd == null)
            {
                _context.ThrowTypeError("Not a callable function");
                return JSValue.Exception;
            }

            var savedFrame = _currentFrame;
            try
            {
                var frame = new CallFrame(fd, thisVal, args, func.VarRefs, savedFrame);
                _currentFrame = frame;
                var result = Execute(fd);
                if (isConstructor && !result.IsObject)
                    return thisVal;
                return result;
            }
            finally
            {
                _currentFrame = savedFrame;
            }
        }

        _context.ThrowTypeError("Not a function");
        return JSValue.Exception;
    }

    #endregion

    #region Stack Operations

    /// <summary>
    /// Pushes a value onto the operand stack.
    /// </summary>
    /// <param name="value">The value to push.</param>
    /// <exception cref="JSException">Thrown when the stack overflows.</exception>
    public void Push(JSValue value)
    {
        if (_stackPointer >= _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer++] = value;
    }

    /// <summary>
    /// Pops a value from the operand stack.
    /// </summary>
    /// <returns>The popped value.</returns>
    /// <exception cref="JSException">Thrown when the stack is empty.</exception>
    public JSValue Pop()
    {
        if (_stackPointer <= 0)
        {
            ThrowStackUnderflow();
            return JSValue.Undefined;
        }
        return _stack[--_stackPointer];
    }

    /// <summary>
    /// Peeks at the top value on the stack without removing it.
    /// </summary>
    /// <returns>The top value.</returns>
    /// <exception cref="JSException">Thrown when the stack is empty.</exception>
    public JSValue Peek()
    {
        if (_stackPointer <= 0)
        {
            ThrowStackUnderflow();
            return JSValue.Undefined;
        }
        return _stack[_stackPointer - 1];
    }

    /// <summary>
    /// Peeks at a value at the specified depth from the top.
    /// </summary>
    /// <param name="depth">The depth from the top (0 = top, 1 = second from top, etc.).</param>
    /// <returns>The value at the specified depth.</returns>
    public JSValue PeekAt(int depth)
    {
        int index = _stackPointer - 1 - depth;
        if (index < 0 || index >= _stackPointer)
        {
            ThrowStackUnderflow();
            return JSValue.Undefined;
        }
        return _stack[index];
    }

    /// <summary>
    /// Drops the top value from the stack (OP_drop).
    /// </summary>
    public void Drop()
    {
        if (_stackPointer > 0)
        {
            _stackPointer--;
        }
    }

    /// <summary>
    /// Duplicates the top value (OP_dup): a -> a a
    /// </summary>
    public void Dup()
    {
        if (_stackPointer <= 0)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer >= _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 1];
        _stackPointer++;
    }

    /// <summary>
    /// Duplicates the top two values (OP_dup2): a b -> a b a b
    /// </summary>
    public void Dup2()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer + 2 > _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 2];
        _stack[_stackPointer + 1] = _stack[_stackPointer - 1];
        _stackPointer += 2;
    }

    /// <summary>
    /// Duplicates the top three values (OP_dup3): a b c -> a b c a b c
    /// </summary>
    public void Dup3()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer + 3 > _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 3];
        _stack[_stackPointer + 1] = _stack[_stackPointer - 2];
        _stack[_stackPointer + 2] = _stack[_stackPointer - 1];
        _stackPointer += 3;
    }

    /// <summary>
    /// Duplicates the second value (OP_dup1): a b -> a a b
    /// </summary>
    public void Dup1()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer >= _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = _stack[_stackPointer - 2];
        _stackPointer++;
    }

    /// <summary>
    /// Removes the second item (OP_nip): a b -> b
    /// </summary>
    public void Nip()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }
        _stack[_stackPointer - 2] = _stack[_stackPointer - 1];
        _stackPointer--;
    }

    /// <summary>
    /// Removes the third item (OP_nip1): a b c -> b c
    /// </summary>
    public void Nip1()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        _stack[_stackPointer - 3] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer - 1];
        _stackPointer--;
    }

    /// <summary>
    /// Swaps the top two values (OP_swap): a b -> b a
    /// </summary>
    public void Swap()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }
        var temp = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = temp;
    }

    /// <summary>
    /// Rotates top three values left (OP_rot3l): x a b -> a b x (231)
    /// </summary>
    public void Rot3L()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        var tmp = _stack[_stackPointer - 3];
        _stack[_stackPointer - 3] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = tmp;
    }

    /// <summary>
    /// Rotates top three values right (OP_rot3r): a b x -> x a b (312)
    /// </summary>
    public void Rot3R()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        var tmp = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer - 3];
        _stack[_stackPointer - 3] = tmp;
    }

    /// <summary>
    /// Permutes top three (OP_perm3): obj a b -> a obj b (213)
    /// </summary>
    public void Perm3()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        var tmp = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer - 3];
        _stack[_stackPointer - 3] = tmp;
    }

    /// <summary>
    /// Insert duplicate at second position (OP_insert2): obj a -> a obj a
    /// </summary>
    public void Insert2()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer >= _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer];
        _stackPointer++;
    }

    /// <summary>
    /// Insert duplicate at third position (OP_insert3): obj prop a -> a obj prop a
    /// </summary>
    public void Insert3()
    {
        if (_stackPointer < 3)
        {
            ThrowStackUnderflow();
            return;
        }
        if (_stackPointer >= _maxStackSize)
        {
            ThrowStackOverflow();
            return;
        }
        _stack[_stackPointer] = _stack[_stackPointer - 1];
        _stack[_stackPointer - 1] = _stack[_stackPointer - 2];
        _stack[_stackPointer - 2] = _stack[_stackPointer - 3];
        _stack[_stackPointer - 3] = _stack[_stackPointer];
        _stackPointer++;
    }

    /// <summary>
    /// Clears the entire stack.
    /// </summary>
    public void ClearStack()
    {
        _stackPointer = 0;
    }

    /// <summary>
    /// Gets a copy of the current stack contents for debugging.
    /// </summary>
    /// <returns>An array of the current stack values.</returns>
    public JSValue[] GetStackSnapshot()
    {
        var snapshot = new JSValue[_stackPointer];
        Array.Copy(_stack, 0, snapshot, 0, _stackPointer);
        return snapshot;
    }

    #endregion

    #region Arithmetic Operations

    /// <summary>
    /// Addition: pops two values, pushes their sum.
    /// Handles int + int, float + float, and string concatenation.
    /// </summary>
    public void Add()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            long result = (long)op1.ToInt32() + op2.ToInt32();
            if (result >= int.MinValue && result <= int.MaxValue)
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32((int)result);
            }
            else
            {
                // Overflow to double
                _stack[_stackPointer - 1] = JSValue.FromDouble(result);
            }
            return;
        }

        // Fast path: both doubles
        if (op1.IsNumber && op2.IsNumber)
        {
            _stack[_stackPointer - 1] = JSValue.FromDouble(op1.ToDouble() + op2.ToDouble());
            return;
        }

        // String concatenation
        if (op1.IsString || op2.IsString)
        {
            string s1 = JSValueConversion.ToString(op1);
            string s2 = JSValueConversion.ToString(op2);
            _stack[_stackPointer - 1] = JSValue.FromString(s1 + s2);
            return;
        }

        // General case: convert to primitives
        AddSlow(op1, op2);
    }

    private void AddSlow(JSValue op1, JSValue op2)
    {
        // ToPrimitive hint: default (number for most, string for Date)
        var prim1 = ToPrimitive(op1);
        var prim2 = ToPrimitive(op2);

        if (prim1.IsString || prim2.IsString)
        {
            string s1 = JSValueConversion.ToString(prim1);
            string s2 = JSValueConversion.ToString(prim2);
            _stack[_stackPointer - 1] = JSValue.FromString(s1 + s2);
        }
        else
        {
            double d1 = JSValueConversion.ToNumber(prim1);
            double d2 = JSValueConversion.ToNumber(prim2);
            _stack[_stackPointer - 1] = JSValue.FromDouble(d1 + d2);
        }
    }

    /// <summary>
    /// Subtraction: pops two values, pushes their difference.
    /// </summary>
    public void Sub()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            long result = (long)op1.ToInt32() - op2.ToInt32();
            if (result >= int.MinValue && result <= int.MaxValue)
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32((int)result);
            }
            else
            {
                _stack[_stackPointer - 1] = JSValue.FromDouble(result);
            }
            return;
        }

        // General case
        double d1 = JSValueConversion.ToNumber(op1);
        double d2 = JSValueConversion.ToNumber(op2);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d1 - d2);
    }

    /// <summary>
    /// Multiplication: pops two values, pushes their product.
    /// </summary>
    public void Mul()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            int v1 = op1.ToInt32();
            int v2 = op2.ToInt32();
            long result = (long)v1 * v2;

            if (result >= int.MinValue && result <= int.MaxValue && !(result == 0 && (v1 | v2) < 0))
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32((int)result);
            }
            else
            {
                // Handle -0 and overflow
                _stack[_stackPointer - 1] = JSValue.FromDouble((double)result);
            }
            return;
        }

        // General case
        double d1 = JSValueConversion.ToNumber(op1);
        double d2 = JSValueConversion.ToNumber(op2);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d1 * d2);
    }

    /// <summary>
    /// Division: pops two values, pushes their quotient.
    /// Always returns a double (JavaScript division is always floating-point).
    /// </summary>
    public void Div()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        double d1 = JSValueConversion.ToNumber(op1);
        double d2 = JSValueConversion.ToNumber(op2);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d1 / d2);
    }

    /// <summary>
    /// Modulo: pops two values, pushes the remainder.
    /// </summary>
    public void Mod()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both positive integers
        if (op1.IsInt && op2.IsInt)
        {
            int v1 = op1.ToInt32();
            int v2 = op2.ToInt32();
            if (v1 >= 0 && v2 > 0)
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32(v1 % v2);
                return;
            }
        }

        // General case: use IEEE 754 remainder
        double d1 = JSValueConversion.ToNumber(op1);
        double d2 = JSValueConversion.ToNumber(op2);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d1 % d2);
    }

    /// <summary>
    /// Power: pops two values, pushes base ** exponent.
    /// </summary>
    public void Pow()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        double d1 = JSValueConversion.ToNumber(op1);
        double d2 = JSValueConversion.ToNumber(op2);
        _stack[_stackPointer - 1] = JSValue.FromDouble(Math.Pow(d1, d2));
    }

    /// <summary>
    /// Unary plus: converts top value to number.
    /// </summary>
    public void Plus()
    {
        if (_stackPointer < 1)
        {
            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];
        if (op.IsNumber)
            return;

        double d = JSValueConversion.ToNumber(op);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d);
    }

    /// <summary>
    /// Unary negation: negates top value.
    /// </summary>
    public void Neg()
    {
        if (_stackPointer < 1)
        {
            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];

        if (op.IsInt)
        {
            int val = op.ToInt32();
            if (val == 0)
            {
                // -0 must be a double
                _stack[_stackPointer - 1] = JSValue.FromDouble(-0.0);
            }
            else if (val == int.MinValue)
            {
                // Overflow
                _stack[_stackPointer - 1] = JSValue.FromDouble(-(double)val);
            }
            else
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32(-val);
            }
            return;
        }

        double d = JSValueConversion.ToNumber(op);
        _stack[_stackPointer - 1] = JSValue.FromDouble(-d);
    }

    /// <summary>
    /// Increment: adds 1 to top value.
    /// </summary>
    public void Inc()
    {
        if (_stackPointer < 1)
        {
            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];

        if (op.IsInt)
        {
            int val = op.ToInt32();
            if (val < int.MaxValue)
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32(val + 1);
                return;
            }
        }

        double d = JSValueConversion.ToNumber(op);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d + 1);
    }

    /// <summary>
    /// Decrement: subtracts 1 from top value.
    /// </summary>
    public void Dec()
    {
        if (_stackPointer < 1)
        {
            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];

        if (op.IsInt)
        {
            int val = op.ToInt32();
            if (val > int.MinValue)
            {
                _stack[_stackPointer - 1] = JSValue.FromInt32(val - 1);
                return;
            }
        }

        double d = JSValueConversion.ToNumber(op);
        _stack[_stackPointer - 1] = JSValue.FromDouble(d - 1);
    }

    #endregion

    #region Bitwise Operations

    /// <summary>
    /// Bitwise NOT: ~a
    /// </summary>
    public void Not()
    {
        if (_stackPointer < 1)
        {
            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];
        int val = JSValueConversion.ToInt32(op);
        _stack[_stackPointer - 1] = JSValue.FromInt32(~val);
    }

    /// <summary>
    /// Bitwise AND: a &amp; b
    /// </summary>
    public void And()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        int v1 = JSValueConversion.ToInt32(op1);
        int v2 = JSValueConversion.ToInt32(op2);
        _stack[_stackPointer - 1] = JSValue.FromInt32(v1 & v2);
    }

    /// <summary>
    /// Bitwise OR: a | b
    /// </summary>
    public void Or()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        int v1 = JSValueConversion.ToInt32(op1);
        int v2 = JSValueConversion.ToInt32(op2);
        _stack[_stackPointer - 1] = JSValue.FromInt32(v1 | v2);
    }

    /// <summary>
    /// Bitwise XOR: a ^ b
    /// </summary>
    public void Xor()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        int v1 = JSValueConversion.ToInt32(op1);
        int v2 = JSValueConversion.ToInt32(op2);
        _stack[_stackPointer - 1] = JSValue.FromInt32(v1 ^ v2);
    }

    /// <summary>
    /// Left shift: a &lt;&lt; b
    /// </summary>
    public void Shl()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        int v1 = JSValueConversion.ToInt32(op1);
        uint v2 = JSValueConversion.ToUInt32(op2);
        int shift = (int)(v2 & 0x1F); // Only use bottom 5 bits
        _stack[_stackPointer - 1] = JSValue.FromInt32(v1 << shift);
    }

    /// <summary>
    /// Signed right shift: a >> b
    /// </summary>
    public void Sar()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        int v1 = JSValueConversion.ToInt32(op1);
        uint v2 = JSValueConversion.ToUInt32(op2);
        int shift = (int)(v2 & 0x1F);
        _stack[_stackPointer - 1] = JSValue.FromInt32(v1 >> shift);
    }

    /// <summary>
    /// Unsigned right shift: a >>> b
    /// </summary>
    public void Shr()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        uint v1 = JSValueConversion.ToUInt32(op1);
        uint v2 = JSValueConversion.ToUInt32(op2);
        int shift = (int)(v2 & 0x1F);
        uint result = v1 >> shift;
        // Result is uint, but fits in int32 range after shift, or we return as double
        if (result <= int.MaxValue)
        {
            _stack[_stackPointer - 1] = JSValue.FromInt32((int)result);
        }
        else
        {
            _stack[_stackPointer - 1] = JSValue.FromDouble(result);
        }
    }

    #endregion

    #region Comparison Operations

    /// <summary>
    /// Less than comparison: a &lt; b
    /// </summary>
    public void Lt()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(op1.ToInt32() < op2.ToInt32());
            return;
        }

        var result = AbstractRelationalComparison(op1, op2, true);
        _stack[_stackPointer - 1] = result ?? JSValue.False;
    }

    /// <summary>
    /// Less than or equal comparison: a &lt;= b
    /// </summary>
    public void Lte()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(op1.ToInt32() <= op2.ToInt32());
            return;
        }

        // a <= b is !(b < a)
        var result = AbstractRelationalComparison(op2, op1, false);
        if (result == null)
        {
            _stack[_stackPointer - 1] = JSValue.False;
        }
        else
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(!result.Value.IsTrue);
        }
    }

    /// <summary>
    /// Greater than comparison: a > b
    /// </summary>
    public void Gt()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(op1.ToInt32() > op2.ToInt32());
            return;
        }

        // a > b is b < a
        var result = AbstractRelationalComparison(op2, op1, false);
        _stack[_stackPointer - 1] = result ?? JSValue.False;
    }

    /// <summary>
    /// Greater than or equal comparison: a >= b
    /// </summary>
    public void Gte()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        // Fast path: both integers
        if (op1.IsInt && op2.IsInt)
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(op1.ToInt32() >= op2.ToInt32());
            return;
        }

        // a >= b is !(a < b)
        var result = AbstractRelationalComparison(op1, op2, true);
        if (result == null)
        {
            _stack[_stackPointer - 1] = JSValue.False;
        }
        else
        {
            _stack[_stackPointer - 1] = JSValue.FromBoolean(!result.Value.IsTrue);
        }
    }

    /// <summary>
    /// Abstract relational comparison as per ECMAScript spec.
    /// Returns null for undefined result (NaN comparisons).
    /// </summary>
    private JSValue? AbstractRelationalComparison(JSValue x, JSValue y, bool leftFirst)
    {
        JSValue px, py;

        if (leftFirst)
        {
            px = ToPrimitive(x, "number");
            py = ToPrimitive(y, "number");
        }
        else
        {
            py = ToPrimitive(y, "number");
            px = ToPrimitive(x, "number");
        }

        // String comparison
        if (px.IsString && py.IsString)
        {
            string sx = px.ToString()!;
            string sy = py.ToString()!;
            return JSValue.FromBoolean(string.Compare(sx, sy, StringComparison.Ordinal) < 0);
        }

        // Numeric comparison
        double nx = JSValueConversion.ToNumber(px);
        double ny = JSValueConversion.ToNumber(py);

        if (double.IsNaN(nx) || double.IsNaN(ny))
            return null;

        return JSValue.FromBoolean(nx < ny);
    }

    /// <summary>
    /// Abstract equality comparison: a == b
    /// </summary>
    public void Eq()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        _stack[_stackPointer - 1] = JSValue.FromBoolean(AbstractEqualityComparison(op1, op2));
    }

    /// <summary>
    /// Abstract inequality comparison: a != b
    /// </summary>
    public void Neq()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        _stack[_stackPointer - 1] = JSValue.FromBoolean(!AbstractEqualityComparison(op1, op2));
    }

    /// <summary>
    /// Strict equality comparison: a === b
    /// </summary>
    public void StrictEq()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        _stack[_stackPointer - 1] = JSValue.FromBoolean(StrictEqualityComparison(op1, op2));
    }

    /// <summary>
    /// Strict inequality comparison: a !== b
    /// </summary>
    public void StrictNeq()
    {
        if (_stackPointer < 2)
        {
            ThrowStackUnderflow();
            return;
        }

        var op2 = _stack[_stackPointer - 1];
        var op1 = _stack[_stackPointer - 2];
        _stackPointer--;

        _stack[_stackPointer - 1] = JSValue.FromBoolean(!StrictEqualityComparison(op1, op2));
    }

    /// <summary>
    /// Abstract equality comparison as per ECMAScript spec (==).
    /// </summary>
    private bool AbstractEqualityComparison(JSValue x, JSValue y)
    {
        // Same type - use strict comparison
        if (x.Tag == y.Tag)
        {
            return StrictEqualityComparison(x, y);
        }

        // null == undefined
        if ((x.IsNull && y.IsUndefined) || (x.IsUndefined && y.IsNull))
        {
            return true;
        }

        // Number == String -> compare as numbers
        if (x.IsNumber && y.IsString)
        {
            return x.ToDouble() == JSValueConversion.ToNumber(y);
        }
        if (x.IsString && y.IsNumber)
        {
            return JSValueConversion.ToNumber(x) == y.ToDouble();
        }

        // Boolean -> Number
        if (x.IsBool)
        {
            return AbstractEqualityComparison(JSValue.FromDouble(x.IsTrue ? 1 : 0), y);
        }
        if (y.IsBool)
        {
            return AbstractEqualityComparison(x, JSValue.FromDouble(y.IsTrue ? 1 : 0));
        }

        // Object == primitive -> compare ToPrimitive(object) with primitive
        if ((x.IsString || x.IsNumber) && y.IsObject)
        {
            return AbstractEqualityComparison(x, ToPrimitive(y));
        }
        if (x.IsObject && (y.IsString || y.IsNumber))
        {
            return AbstractEqualityComparison(ToPrimitive(x), y);
        }

        return false;
    }

    /// <summary>
    /// Strict equality comparison as per ECMAScript spec (===).
    /// </summary>
    private bool StrictEqualityComparison(JSValue x, JSValue y)
    {
        // Different types are never strictly equal
        if (x.Tag != y.Tag)
        {
            // Handle int32 vs float64 special case
            if (x.IsNumber && y.IsNumber)
            {
                return x.ToDouble() == y.ToDouble();
            }
            return false;
        }

        // Undefined === Undefined
        if (x.IsUndefined)
            return true;

        // Null === Null
        if (x.IsNull)
            return true;

        // Number comparison
        if (x.IsNumber)
        {
            double dx = x.ToDouble();
            double dy = y.ToDouble();
            // NaN is not equal to itself
            if (double.IsNaN(dx) || double.IsNaN(dy))
                return false;
            return dx == dy;
        }

        // String comparison
        if (x.IsString)
        {
            return x.ToString() == y.ToString();
        }

        // Boolean comparison
        if (x.IsBool)
        {
            return x.IsTrue == y.IsTrue;
        }

        // Object comparison - reference equality
        if (x.IsObject)
        {
            return ReferenceEquals(x.AsObject(), y.AsObject());
        }

        return false;
    }

