            ThrowStackUnderflow();
            return;
        }

        var op = _stack[_stackPointer - 1];
        bool truthy = JSValueConversion.ToBoolean(op);
        _stack[_stackPointer - 1] = JSValue.FromBoolean(!truthy);
    }

