    /// Pushes null onto the stack.
    /// </summary>
    public void PushNull()
    {
        Push(JSValue.Null);
    }

    /// <summary>
    /// Pushes true onto the stack.
    /// </summary>
    public void PushTrue()
    {
        Push(JSValue.True);
