    /// <summary>
    /// Pushes a 32-bit integer onto the stack.
    /// </summary>
    /// <param name="value">The integer value to push.</param>
    public void PushI32(int value)
    {
        Push(JSValue.FromInt32(value));
    }

    /// <summary>
    /// Pushes a double onto the stack.
    /// </summary>
    /// <param name="value">The double value to push.</param>
    public void PushDouble(double value)
    {
        Push(JSValue.FromDouble(value));
    }

    /// <summary>
    /// Pushes a string onto the stack.
    /// </summary>
    /// <param name="value">The string value to push.</param>
    public void PushString(string value)
    {
        Push(JSValue.FromString(value));
    }

    #endregion

    #region Type Conversion Helpers

    /// <summary>
    /// Converts a value to its primitive representation.
    /// </summary>
    /// <param name="value">The value to convert.</param>
    /// <param name="preferredType">The preferred type hint ("string" or "number").</param>
    /// <returns>The primitive value.</returns>
    private JSValue ToPrimitive(JSValue value, string? preferredType = null)
    {
        if (!value.IsObject)
            return value;

        // TODO: Implement proper ToPrimitive with valueOf/toString calls
        // For now, just convert to string for objects
        return JSValue.FromString(value.ToString() ?? "[object Object]");
    }

    #endregion

    #region Bytecode Execution

    /// <summary>
    /// Executes a single opcode.
    /// </summary>
    /// <param name="opcode">The opcode to execute.</param>
    /// <returns>True if execution should continue, false if complete or exception.</returns>
    public bool ExecuteOpCode(OpCode opcode)
    {
        switch (opcode)
        {
            // Push values
            case OpCode.Undefined:
                PushUndefined();
                return true;
            case OpCode.Null:
                PushNull();
                return true;
            case OpCode.PushTrue:
                PushTrue();
                return true;
            case OpCode.PushThis:
                if (_currentFrame != null)
                    Push(_currentFrame.ThisValue);
                else
                    Push(JSValue.Undefined);
                return true;
            case OpCode.PushFalse:
                PushFalse();
                return true;

            // Stack operations
            case OpCode.Drop:
                Drop();
                return true;
            case OpCode.Dup:
                Dup();
                return true;
            case OpCode.Dup2:
                Dup2();
                return true;
            case OpCode.Dup3:
                Dup3();
                return true;
            case OpCode.Dup1:
                Dup1();
                return true;
            case OpCode.Nip:
                Nip();
                return true;
            case OpCode.Nip1:
                Nip1();
                return true;
            case OpCode.Swap:
                Swap();
                return true;
            case OpCode.Rot3L:
                Rot3L();
                return true;
            case OpCode.Rot3R:
                Rot3R();
                return true;
            case OpCode.Perm3:
                Perm3();
                return true;
            case OpCode.Insert2:
                Insert2();
                return true;
            case OpCode.Insert3:
                Insert3();
                return true;

            // Arithmetic
            case OpCode.Add:
                Add();
                return true;
            case OpCode.Sub:
                Sub();
                return true;
            case OpCode.Mul:
                Mul();
                return true;
            case OpCode.Div:
                Div();
                return true;
            case OpCode.Mod:
                Mod();
                return true;
            case OpCode.Pow:
                Pow();
                return true;
            case OpCode.Plus:
                Plus();
                return true;
            case OpCode.Neg:
                Neg();
                return true;
            case OpCode.Inc:
                Inc();
                return true;
            case OpCode.Dec:
                Dec();
                return true;

            // Bitwise
            case OpCode.Not:
                Not();
                return true;
            case OpCode.And:
                And();
                return true;
            case OpCode.Or:
                Or();
                return true;
            case OpCode.Xor:
                Xor();
                return true;
            case OpCode.Shl:
                Shl();
                return true;
            case OpCode.Sar:
                Sar();
                return true;
            case OpCode.Shr:
                Shr();
                return true;

            // Comparison
            case OpCode.Lt:
                Lt();
                return true;
            case OpCode.Lte:
                Lte();
                return true;
            case OpCode.Gt:
                Gt();
                return true;
            case OpCode.Gte:
                Gte();
                return true;
            case OpCode.Eq:
                Eq();
                return true;
            case OpCode.Neq:
                Neq();
                return true;
            case OpCode.StrictEq:
                StrictEq();
                return true;
            case OpCode.StrictNeq:
                StrictNeq();
                return true;

            // Logical
            case OpCode.LNot:
                LogicalNot();
                return true;
            case OpCode.IsUndefinedOrNull:
                IsUndefinedOrNull();
                return true;

            // Array element access (no operands)
            case OpCode.GetArrayEl:
                GetArrayEl();
                return true;
            case OpCode.GetArrayEl2:
                GetArrayEl2();
                return true;
            case OpCode.PutArrayEl:
                PutArrayEl();
                return true;

                // Control flow (short forms handled in Execute loop)
                case OpCode.IfFalse:
                case OpCode.IfTrue:
                case OpCode.Goto:
                case OpCode.IfFalse8:
                case OpCode.IfTrue8:
                case OpCode.Goto8:
                case OpCode.Goto16:
                    // These are handled in Execute where the PC is available
                    _context.ThrowTypeError($"Unexpected control flow opcode in ExecuteOpCode: {opcode}");
                    return false;

            default:
                // Unhandled opcode
                _context.ThrowTypeError($"Unhandled opcode: {opcode}");
                return false;
        }
    }

    /// <summary>
    /// Executes bytecode from a function definition.
    /// </summary>
    /// <param name="function">The function to execute.</param>
    /// <returns>The result of execution.</returns>
    public JSValue Execute(JSFunctionDef function)
    {
        if (function == null)
            throw new ArgumentNullException(nameof(function));

        var bytecode = function.ByteCode.ToArray();
        int pc = 0;

        JSValue returnValue = JSValue.Undefined;
        bool didReturn = false;

        while (pc < bytecode.Length && !HasException && !didReturn)
        {
            var opcode = (OpCode)bytecode[pc++];

            switch (opcode)
            {
                case OpCode.PushConst:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int constIdx = bytecode[pc] |
                                       (bytecode[pc + 1] << 8) |
                                       (bytecode[pc + 2] << 16) |
                                       (bytecode[pc + 3] << 24);
                        pc += 4;
                        if (constIdx < 0 || constIdx >= function.Constants.Count)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Invalid constant index");
                            return JSValue.Exception;
                        }
                        Push(function.Constants.Get(constIdx));
                    }
                    break;

                case OpCode.PushI32:
                    if (pc + 4 > bytecode.Length)
                    {
                        _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                        return JSValue.Exception;
                    }
                    int i32 = bytecode[pc] |
                             (bytecode[pc + 1] << 8) |
                             (bytecode[pc + 2] << 16) |
                             (bytecode[pc + 3] << 24);
                    pc += 4;
                    PushI32(i32);
                    break;

                // Local variable access (u16 index)
                case OpCode.GetLoc:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        GetLoc(idx);
                    }
                    break;

                // Function calls
                case OpCode.Call:
                case OpCode.TailCall:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        ushort argc = (ushort)(bytecode[pc] | (bytecode[pc + 1] << 8));
                        pc += 2;
                        if (_stackPointer < argc + 1)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Stack underflow during call");
                            return JSValue.Exception;
                        }
                        int calleeIndex = _stackPointer - argc - 1;
                        var callee = _stack[calleeIndex];
                        var args = new JSValue[argc];
                        Array.Copy(_stack, _stackPointer - argc, args, 0, argc);

                        var result = CallFunction(callee, JSValue.Undefined, args);
                        if (result.IsException)
                            return JSValue.Exception;

                        // Pop callee and args
                        _stackPointer -= argc + 1;
                        // Push result
                        Push(result);
                    }
                    break;

                case OpCode.CallMethod:
                case OpCode.TailCallMethod:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        ushort argc = (ushort)(bytecode[pc] | (bytecode[pc + 1] << 8));
                        pc += 2;
                        if (_stackPointer < argc + 2)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Stack underflow during method call");
                            return JSValue.Exception;
                        }
                        int thisIndex = _stackPointer - argc - 2;
                        int calleeIndex = _stackPointer - argc - 1;
                        var thisVal = _stack[thisIndex];
                        var callee = _stack[calleeIndex];
                        var args = new JSValue[argc];
                        Array.Copy(_stack, _stackPointer - argc, args, 0, argc);

                        var result = CallFunction(callee, thisVal, args);
                        if (result.IsException)
                            return JSValue.Exception;

                        _stackPointer -= argc + 2;
                        Push(result);
                    }
                    break;

                case OpCode.CallConstructor:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        ushort argc = (ushort)(bytecode[pc] | (bytecode[pc + 1] << 8));
                        pc += 2;
                        if (_stackPointer < argc + 2)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Stack underflow during constructor call");
                            return JSValue.Exception;
                        }
                        int funcIndex = _stackPointer - argc - 2;
                        int newTargetIndex = _stackPointer - argc - 1;
                        var funcVal = _stack[funcIndex];
                        var newTarget = _stack[newTargetIndex];
                        var args = new JSValue[argc];
                        Array.Copy(_stack, _stackPointer - argc, args, 0, argc);

                        // Allocate a simple object with prototype from function if available
                        JSValue thisVal = JSValue.FromObject(new JSObject());
                        if (funcVal.IsObject && funcVal.AsObject() is JSFunction f && f.Prototype is JSObject proto)
                        {
                            thisVal = JSValue.FromObject(new JSObject(proto));
                        }

                        var result = CallFunction(funcVal, thisVal, args, isConstructor: true);
                        if (result.IsException)
                            return JSValue.Exception;

                        _stackPointer -= argc + 2;
                        Push(result);
                    }
                    break;

                // Small fixed-arity calls: func arg0...argN
                case OpCode.Call0:
                case OpCode.Call1:
                case OpCode.Call2:
                case OpCode.Call3:
                    {
                        int argc = opcode switch
                        {
                            OpCode.Call0 => 0,
                            OpCode.Call1 => 1,
                            OpCode.Call2 => 2,
                            OpCode.Call3 => 3,
                            _ => 0
                        };
                        if (_stackPointer < argc + 1)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Stack underflow during callN");
                            return JSValue.Exception;
                        }
                        int calleeIndex = _stackPointer - argc - 1;
                        var callee = _stack[calleeIndex];
                        var args = new JSValue[argc];
                        if (argc > 0)
                        {
                            Array.Copy(_stack, _stackPointer - argc, args, 0, argc);
                        }

                        var result = CallFunction(callee, JSValue.Undefined, args);
                        if (result.IsException)
                            return JSValue.Exception;

                        _stackPointer -= argc + 1;
                        Push(result);
                    }
                    break;

                case OpCode.PutLoc:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutLoc(idx);
                    }
                    break;

                case OpCode.SetLoc:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        SetLoc(idx);
                    }
                    break;

                // Argument access (u16 index)
                case OpCode.GetArg:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        GetArg(idx);
                    }
                    break;

                case OpCode.PutArg:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutArg(idx);
                    }
                    break;

                case OpCode.SetArg:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        SetArg(idx);
                    }
                    break;

                // Var ref access (u16 index)
                case OpCode.GetVarRef:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        GetVarRef(idx);
                    }
                    break;

                case OpCode.PutVarRef:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutVarRef(idx);
                    }
                    break;

                case OpCode.SetVarRef:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        SetVarRef(idx);
                    }
                    break;

                // TDZ-checked access
                case OpCode.GetLocCheck:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        GetLocCheck(idx);
                    }
                    break;

                case OpCode.PutLocCheck:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutLocCheck(idx);
                    }
                    break;

                case OpCode.PutLocCheckInit:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutLocCheckInit(idx);
                    }
                    break;

                case OpCode.GetVarRefCheck:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        GetVarRefCheck(idx);
                    }
                    break;

                case OpCode.PutVarRefCheck:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        PutVarRefCheck(idx);
                    }
                    break;

                case OpCode.SetLocUninitialized:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc] | (bytecode[pc + 1] << 8);
                        pc += 2;
                        SetLocUninitialized(idx);
                    }
                    break;

                // Property access (u32 atom)
                case OpCode.GetField:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        uint atom = (uint)(bytecode[pc] |
                                          (bytecode[pc + 1] << 8) |
                                          (bytecode[pc + 2] << 16) |
                                          (bytecode[pc + 3] << 24));
                        pc += 4;
                        string propName = _context.Runtime.AtomTable.GetString(new JSAtom(atom));
                        GetField(propName);
                    }
                    break;

                case OpCode.GetField2:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        uint atom = (uint)(bytecode[pc] |
                                          (bytecode[pc + 1] << 8) |
                                          (bytecode[pc + 2] << 16) |
                                          (bytecode[pc + 3] << 24));
                        pc += 4;
                        string propName = _context.Runtime.AtomTable.GetString(new JSAtom(atom));
                        GetField2(propName);
                    }
                    break;

                case OpCode.PutField:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        uint atom = (uint)(bytecode[pc] |
                                          (bytecode[pc + 1] << 8) |
                                          (bytecode[pc + 2] << 16) |
                                          (bytecode[pc + 3] << 24));
                        pc += 4;
                        string propName = _context.Runtime.AtomTable.GetString(new JSAtom(atom));
                        PutField(propName);
                    }
                    break;

                case OpCode.DefineField:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        uint atom = (uint)(bytecode[pc] |
                                          (bytecode[pc + 1] << 8) |
                                          (bytecode[pc + 2] << 16) |
                                          (bytecode[pc + 3] << 24));
                        pc += 4;
                        string propName = _context.Runtime.AtomTable.GetString(new JSAtom(atom));
                        DefineField(propName);
                    }
                    break;

                // Short opcodes for common local indices
                case OpCode.GetLoc0:
                    GetLoc(0);
                    break;
                case OpCode.GetLoc1:
                    GetLoc(1);
                    break;
                case OpCode.GetLoc2:
                    GetLoc(2);
                    break;
                case OpCode.GetLoc3:
                    GetLoc(3);
                    break;
                case OpCode.PutLoc0:
                    PutLoc(0);
                    break;
                case OpCode.PutLoc1:
                    PutLoc(1);
                    break;
                case OpCode.PutLoc2:
                    PutLoc(2);
                    break;
                case OpCode.PutLoc3:
                    PutLoc(3);
                    break;
                case OpCode.SetLoc0:
                    SetLoc(0);
                    break;
                case OpCode.SetLoc1:
                    SetLoc(1);
                    break;
                case OpCode.SetLoc2:
                    SetLoc(2);
                    break;
                case OpCode.SetLoc3:
                    SetLoc(3);
                    break;

                // Short opcodes for common arg indices
                case OpCode.GetArg0:
                    GetArg(0);
                    break;
                case OpCode.GetArg1:
                    GetArg(1);
                    break;
                case OpCode.GetArg2:
                    GetArg(2);
                    break;
                case OpCode.GetArg3:
                    GetArg(3);
                    break;
                case OpCode.PutArg0:
                    PutArg(0);
                    break;
                case OpCode.PutArg1:
                    PutArg(1);
                    break;
                case OpCode.PutArg2:
                    PutArg(2);
                    break;
                case OpCode.PutArg3:
                    PutArg(3);
                    break;
                case OpCode.SetArg0:
                    SetArg(0);
                    break;
                case OpCode.SetArg1:
                    SetArg(1);
                    break;
                case OpCode.SetArg2:
                    SetArg(2);
                    break;
                case OpCode.SetArg3:
                    SetArg(3);
                    break;

                // Short opcodes for common var ref indices
                case OpCode.GetVarRef0:
                    GetVarRef(0);
                    break;
                case OpCode.GetVarRef1:
                    GetVarRef(1);
                    break;
                case OpCode.GetVarRef2:
                    GetVarRef(2);
                    break;
                case OpCode.GetVarRef3:
                    GetVarRef(3);
                    break;
                case OpCode.PutVarRef0:
                    PutVarRef(0);
                    break;
                case OpCode.PutVarRef1:
                    PutVarRef(1);
                    break;
                case OpCode.PutVarRef2:
                    PutVarRef(2);
                    break;
                case OpCode.PutVarRef3:
                    PutVarRef(3);
                    break;
                case OpCode.SetVarRef0:
                    SetVarRef(0);
                    break;
                case OpCode.SetVarRef1:
                    SetVarRef(1);
                    break;
                case OpCode.SetVarRef2:
                    SetVarRef(2);
                    break;
                case OpCode.SetVarRef3:
                    SetVarRef(3);
                    break;

                // u8 short opcodes
                case OpCode.GetLoc8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc++];
                        GetLoc(idx);
                    }
                    break;
                case OpCode.PutLoc8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc++];
                        PutLoc(idx);
                    }
                    break;
                case OpCode.SetLoc8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int idx = bytecode[pc++];
                        SetLoc(idx);
                    }
                    break;

                // Control flow: conditional and unconditional jumps (32-bit offsets)
                case OpCode.IfFalse:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int offset = bytecode[pc] |
                                    (bytecode[pc + 1] << 8) |
                                    (bytecode[pc + 2] << 16) |
                                    (bytecode[pc + 3] << 24);
                        pc += 4;
                        var cond = Pop();
                        if (!JSValueConversion.ToBoolean(cond))
                        {
                            pc += offset;
                        }
                    }
                    break;

                case OpCode.IfTrue:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int offset = bytecode[pc] |
                                    (bytecode[pc + 1] << 8) |
                                    (bytecode[pc + 2] << 16) |
                                    (bytecode[pc + 3] << 24);
                        pc += 4;
                        var cond = Pop();
                        if (JSValueConversion.ToBoolean(cond))
                        {
                            pc += offset;
                        }
                    }
                    break;

                case OpCode.Goto:
                    {
                        if (pc + 4 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        int offset = bytecode[pc] |
                                    (bytecode[pc + 1] << 8) |
                                    (bytecode[pc + 2] << 16) |
                                    (bytecode[pc + 3] << 24);
                        pc += 4;
                        pc += offset;
                    }
                    break;

                // Control flow: short jumps (8-bit signed offsets)
                case OpCode.IfFalse8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        sbyte offset = unchecked((sbyte)bytecode[pc++]);
                        var cond = Pop();
                        if (!JSValueConversion.ToBoolean(cond))
                        {
                            pc += offset;
                        }
                    }
                    break;

                case OpCode.IfTrue8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        sbyte offset = unchecked((sbyte)bytecode[pc++]);
                        var cond = Pop();
                        if (JSValueConversion.ToBoolean(cond))
                        {
                            pc += offset;
                        }
                    }
                    break;

                case OpCode.Goto8:
                    {
                        if (pc >= bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        sbyte offset = unchecked((sbyte)bytecode[pc++]);
                        pc += offset;
                    }
                    break;

                // Control flow: 16-bit signed offset jump
                case OpCode.Goto16:
                    {
                        if (pc + 2 > bytecode.Length)
                        {
                            _context.ThrowError(JSErrorType.RangeError, "Bytecode overrun");
                            return JSValue.Exception;
                        }
                        short offset = (short)(bytecode[pc] | (bytecode[pc + 1] << 8));
                        pc += 2;
                        pc += offset;
                    }
                    break;

                // Function returns
                case OpCode.Return:
                    returnValue = Pop();
                    didReturn = true;
                    break;
                case OpCode.ReturnUndef:
                    returnValue = JSValue.Undefined;
                    didReturn = true;
                    break;

                default:
                    if (!ExecuteOpCode(opcode))
                        return JSValue.Exception;
                    break;
            }
        }

        return didReturn ? returnValue : (_stackPointer > 0 ? Pop() : JSValue.Undefined);
    }

    #endregion

    #region Exception Helpers

    private void ThrowStackOverflow()
    {
        _context.ThrowError(JSErrorType.RangeError, "Stack overflow");
    }

    private void ThrowStackUnderflow()
    {
        _context.ThrowError(JSErrorType.RangeError, "Stack underflow");
    }

    #endregion
}
